using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
namespace NightLens {
public static class ObjectImages {
 public static string CacheFolder=Path.Combine(Settings.Folder,"ObjectImages");static readonly object gate=new object();static Dictionary<string,Task<string>> jobs=new Dictionary<string,Task<string>>();static Dictionary<string,DateTime> failed=new Dictionary<string,DateTime>();static Dictionary<string,string> errors=new Dictionary<string,string>();static Dictionary<string,Tuple<long,DateTime>> validated=new Dictionary<string,Tuple<long,DateTime>>();static HashSet<string> broken=new HashSet<string>();internal static Func<string,byte[]> Downloader=DownloadBytes;
 public static double Field(Target t){return Math.Max(15,Math.Min(120,t.Major>0?t.Major*1.5:30));}
 public static string Url(Target t){return "https://alasky.cds.unistra.fr/hips-image-services/hips2fits?hips=CDS%2FP%2FDSS2%2Fcolor&width=1200&height=1200&projection=TAN&coordsys=icrs&ra="+(t.Ra*15).ToString("0.000000",CultureInfo.InvariantCulture)+"&dec="+t.Dec.ToString("0.000000",CultureInfo.InvariantCulture)+"&fov="+(Field(t)/60).ToString("0.000000",CultureInfo.InvariantCulture)+"&format=jpg";}
 public static string Source(Target t){if(!t.Body.HasValue)return "CDS / STScI DSS2 color composite; "+Field(t).ToString("0.#")+"′ central field. https://alasky.cds.unistra.fr/DSS/DSSColor/properties";switch(t.Body.Value){case CosineKitty.Body.Moon:return "NASA/JPL/USGS, Galileo Moon color photograph PIA00405 · https://images.nasa.gov/details/PIA00405";case CosineKitty.Body.Jupiter:return "NASA/JPL/Space Science Institute, Cassini PIA02873";case CosineKitty.Body.Saturn:return "NASA/JPL/Space Science Institute, Cassini PIA11141";case CosineKitty.Body.Mars:return "NASA/JPL/USGS, Viking PIA00407";default:return "NASA/JPL, Magellan radar rendering PIA00271 (not an optical view)";}}
 public static string SourceUrl(Target t){if(!t.Body.HasValue)return Url(t);if(t.Body==CosineKitty.Body.Moon)return "https://images.nasa.gov/details/PIA00405";string id=t.Body==CosineKitty.Body.Jupiter?"PIA02873":t.Body==CosineKitty.Body.Saturn?"PIA11141":t.Body==CosineKitty.Body.Mars?"PIA00407":"PIA00271";return "https://images.nasa.gov/details/"+id;}
 public static string Caption(Target t){return t.Body.HasValue?(t.Body==CosineKitty.Body.Venus?"NASA radar rendering · reference":"NASA color reference"):"DSS2 color · "+Field(t).ToString("0.#")+"′ field · reference";}
 public static string PathFor(Target t){if(t.Body.HasValue)return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Assets","Objects",t.Body.Value.ToString()+".jpg");using(var sha=SHA256.Create()){string key=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(Url(t)))).Replace("-","").Substring(0,24);return Path.Combine(CacheFolder,key+".png");}}
 public static string ErrorFor(Target t){lock(gate){string value;return errors.TryGetValue(PathFor(t),out value)?value:"Image service is temporarily unavailable.";}}
 public static void ReportReadError(Target t){lock(gate){string path=PathFor(t);validated.Remove(path);broken.Add(path);errors[path]="The cached picture could not be opened.";}}
 static bool ValidCache(string path){try{if(!File.Exists(path))return false;var info=new FileInfo(path);lock(gate){Tuple<long,DateTime> old;if(broken.Contains(path))return false;if(validated.TryGetValue(path,out old)&&old.Item1==info.Length&&old.Item2==info.LastWriteTimeUtc)return true;}using(var stream=File.Open(path,FileMode.Open,FileAccess.Read,FileShare.Read))using(var image=Image.FromStream(stream,false,true))using(var decoded=new Bitmap(image)){if(image.Width<1||image.Height<1||image.Width>6000||image.Height>6000)return false;}lock(gate)validated[path]=Tuple.Create(info.Length,info.LastWriteTimeUtc);return true;}catch{return false;}}
 public static Task<string> Get(Target t,bool online,bool forceRetry=false){string path=PathFor(t);if(ValidCache(path))return Task.FromResult(path);if(!online||t.Body.HasValue)return Task.FromResult<string>(null);lock(gate){Task<string> old;if(jobs.TryGetValue(path,out old)){if(!old.IsCompleted)return old;jobs.Remove(path);}DateTime when;if(!forceRetry&&failed.TryGetValue(path,out when)&&(DateTime.UtcNow-when).TotalSeconds<20)return Task.FromResult<string>(null);failed.Remove(path);var task=Task.Run(()=>{string result=Fetch(t,path);lock(gate){if(result==null)failed[path]=DateTime.UtcNow;}return result;});jobs[path]=task;task.ContinueWith(done=>{lock(gate){Task<string> current;if(jobs.TryGetValue(path,out current)&&ReferenceEquals(current,task))jobs.Remove(path);}});return task;}}
 static byte[] DownloadBytes(string url){var request=(HttpWebRequest)WebRequest.Create(url);request.Timeout=30000;request.ReadWriteTimeout=30000;request.UserAgent="NightLens/7.4 personal astronomy planner";request.ServicePoint.ConnectionLimit=Math.Max(4,request.ServicePoint.ConnectionLimit);using(var response=request.GetResponse())using(var stream=response.GetResponseStream())using(var buffer=new MemoryStream()){byte[] bytes=new byte[8192];int n;while((n=stream.Read(bytes,0,bytes.Length))>0){if(buffer.Length+n>12*1024*1024)throw new IOException("Image exceeds download size limit.");buffer.Write(bytes,0,n);}return buffer.ToArray();}}
 static string Friendly(Exception error){var web=error as WebException;if(web!=null){if(web.Status==WebExceptionStatus.Timeout)return "The image service took too long to respond.";if(web.Status==WebExceptionStatus.NameResolutionFailure||web.Status==WebExceptionStatus.ConnectFailure)return "Cannot reach the image service.";if(web.Status==WebExceptionStatus.ProtocolError)return "The image server returned an error.";}if(error is UnauthorizedAccessException)return "The image cache could not be saved.";if(error is ArgumentException)return "The image server returned an incomplete picture.";return "The reference picture could not be loaded.";}
 static void Log(Target t,string url,Exception error){try{lock(gate){Directory.CreateDirectory(CacheFolder);string path=Path.Combine(CacheFolder,"image-errors.log");string line=DateTime.UtcNow.ToString("o")+" | "+(t.Canonical??t.Name)+" | "+new Uri(url).Host+" | "+error.GetType().Name+": "+error.Message+Environment.NewLine;if(File.Exists(path)&&new FileInfo(path).Length>200000)File.WriteAllText(path,line);else File.AppendAllText(path,line);}}catch{}}
 static string Fetch(Target t,string path){foreach(string url in new[]{Url(t),Url(t).Replace("alasky.cds.unistra.fr","alaskybis.cds.unistra.fr")}){string temporary=null;try{byte[] bytes=Downloader(url);if(bytes.Length>12*1024*1024)throw new IOException("Image exceeds download size limit.");using(var buffer=new MemoryStream(bytes))using(var original=Image.FromStream(buffer,false,true)){if(original.Width<1||original.Height<1||original.Width>6000||original.Height>6000)throw new IOException("Image dimensions out of range.");using(var image=new Bitmap(original)){Directory.CreateDirectory(CacheFolder);temporary=path+"."+Guid.NewGuid().ToString("N")+".tmp";image.Save(temporary,ImageFormat.Png);if(File.Exists(path))File.Replace(temporary,path,null);else File.Move(temporary,path);temporary=null;}}lock(gate){broken.Remove(path);validated.Remove(path);errors.Remove(path);failed.Remove(path);}return path;}catch(Exception error){lock(gate)errors[path]=Friendly(error);Log(t,url,error);}finally{if(temporary!=null)try{File.Delete(temporary);}catch{}}}return null;}
}
}
